import java.util.Objects;

public final class QuickSort {
    private QuickSort() {
    }

    public static void sort(int[] values) {
        Objects.requireNonNull(values, "values");

        if (values.length < 2) {
            return;
        }

        quickSort(values, 0, values.length - 1);
    }

    private static void quickSort(int[] values, int startIndex, int endIndex) {
        while (startIndex < endIndex) {
            int pivotIndex = partition(values, startIndex, endIndex);

            int leftPartitionSize = pivotIndex - startIndex;
            int rightPartitionSize = endIndex - pivotIndex;

            // Recurse into the smaller partition first to limit stack growth.
            if (leftPartitionSize < rightPartitionSize) {
                quickSort(values, startIndex, pivotIndex - 1);
                startIndex = pivotIndex + 1;
            } else {
                quickSort(values, pivotIndex + 1, endIndex);
                endIndex = pivotIndex - 1;
            }
        }
    }

    private static int partition(int[] values, int startIndex, int endIndex) {
        int pivotIndex = choosePivotIndex(startIndex, endIndex);
        int pivot = values[pivotIndex];
        int nextLowerValueIndex = startIndex;

        swap(values, pivotIndex, endIndex);

        for (int currentIndex = startIndex; currentIndex < endIndex; currentIndex++) {
            if (values[currentIndex] < pivot) {
                swap(values, nextLowerValueIndex, currentIndex);
                nextLowerValueIndex++;
            }
        }

        swap(values, nextLowerValueIndex, endIndex);
        return nextLowerValueIndex;
    }

    private static int choosePivotIndex(int startIndex, int endIndex) {
        return startIndex + (endIndex - startIndex) / 2;
    }

    private static void swap(int[] values, int firstIndex, int secondIndex) {
        if (firstIndex == secondIndex) {
            return;
        }

        int temporaryValue = values[firstIndex];
        values[firstIndex] = values[secondIndex];
        values[secondIndex] = temporaryValue;
    }

    public static void main(String[] args) {
        QuickSortDemo.main(args);
    }
}

import java.util.Arrays;

public final class QuickSortTest {
    private QuickSortTest() {
    }

    public static void main(String[] args) {
        for (SortScenario scenario : sortScenarios()) {
            assertSorted(scenario);
        }

        assertNullRejected();
        assertFormattedValues();
    }

    private static SortScenario[] sortScenarios() {
        return new SortScenario[] {
            new SortScenario(
                    "sample values",
                    new int[] {10, 7, 8, 9, 1, 5},
                    new int[] {1, 5, 7, 8, 9, 10}),
            new SortScenario("empty array", new int[] {}, new int[] {}),
            new SortScenario("single value", new int[] {4}, new int[] {4}),
            new SortScenario(
                    "duplicate values",
                    new int[] {3, 1, 3, 2, 1},
                    new int[] {1, 1, 2, 3, 3}),
            new SortScenario(
                    "negative values",
                    new int[] {0, -4, 8, -1},
                    new int[] {-4, -1, 0, 8}),
            new SortScenario(
                    "already sorted values",
                    new int[] {1, 2, 3, 4, 5},
                    new int[] {1, 2, 3, 4, 5}),
            new SortScenario(
                    "reverse sorted values",
                    new int[] {5, 4, 3, 2, 1},
                    new int[] {1, 2, 3, 4, 5})
        };
    }

    private static void assertSorted(SortScenario scenario) {
        QuickSort.sort(scenario.values);

        if (!Arrays.equals(scenario.values, scenario.expectedValues)) {
            throw new AssertionError(
                    scenario.name
                            + ": expected "
                            + Arrays.toString(scenario.expectedValues)
                            + " but got "
                            + Arrays.toString(scenario.values));
        }
    }

    private static void assertNullRejected() {
        try {
            QuickSort.sort(null);
            throw new AssertionError("null values should be rejected");
        } catch (NullPointerException expected) {
            // Expected by the public sorting contract.
        }
    }

    private static void assertFormattedValues() {
        String formattedValues = QuickSortDemo.formatValues(new int[] {1, 5, 7});

        if (!"1 5 7 ".equals(formattedValues)) {
            throw new AssertionError("formatted values should preserve the legacy console output");
        }
    }

    private static final class SortScenario {
        private final String name;
        private final int[] values;
        private final int[] expectedValues;

        private SortScenario(String name, int[] values, int[] expectedValues) {
            this.name = name;
            this.values = values;
            this.expectedValues = expectedValues;
        }
    }
}
